fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    
    // Handle edge cases: empty or single-element vector
    if n <= 1 {
        return numbers;
    }
    
    // Create result vector with exact capacity
    let mut result = Vec::with_capacity(2 * n - 1);
    
    // Add all elements with delimiters between them
    for (i, &num) in numbers.iter().enumerate() {
        result.push(num);
        
        // Add delimiter after each element except the last one
        if i < n - 1 {
            result.push(delimiter);
        }
    }
    
    result
}